/* PARENT NOTE SHAPE, LIVE. Generated by scripts/build-parent-shape-live.mjs;
 * edit the fixture, the checker or the runner, never this file.
 *
 * Paste the whole file into the browser console on tools.nooutco.me/notes/bcba/
 * while logged in. It drafts the 4 invented cases in
 * tests/fixtures/parent-note-shape.json with your style card and voice block,
 * scores each draft with scripts/lib/parent-shape-checks.mjs, prints a table
 * and puts the results and the drafts on your clipboard.
 *
 * It costs 4 drafts and sends only the invented cases below.
 *
 * The system prompt comes from the prompt store, not from this page. Until the
 * parent prompt change is deployed and re-extracted into the store, a run
 * scores the OLD prompt: a baseline to compare the after-run against. */
(() => {
  const CASES = [
    {
      "id": "v1-the-original-shape",
      "intake": "Goals assessed in parent training session included parent goals, client skill goals, and client behavior goals.\nClient Goals:\nComplete Functional One-Step Instructions (Listener Resp.)|\"Stand up\" + raise hands|0/3|%O\n2. Climbing (Bx Reduction) 2 instances during parent training portion of the session.\nParent Goals:\n1. Parent Goal: Implement Toilet Training Plan|Prompt to Sit for Interval|2/0|100%|+,+\n2. Parent Goal: Implement Toilet Training Plan|Prompt to Go to Bathroom|2/0|100%|+,+\n3. Parent Goal: Implement Toilet Training Plan|Use Timer|2/0|100%|+,+\nBCBA met with caregivers and reviewed an upcoming staff transition the parents requested. Onboarding of a new technician begins in the next 2 weeks.",
      "answers": [
        {
          "question": "You wrote 0/3 on the one-step instruction. What happened on those trials?",
          "answer": "Tantrum behavior occurred on 1 trial, and the other 2 were completed with a physical prompt. The program is to complete them with a gesture prompt."
        },
        {
          "question": "Climbing: how did caregivers respond?",
          "answer": "Add Parent Goal: Implement BIP Climbing: Prompt FCR (Antecedent) 6/1 85%. Parents prompted FCR 5 times when precursors were observed, and climbing happened in 1 of those 5. The BT was running the session earlier while BCBA revised a protocol."
        }
      ],
      "expect": {
        "goalNames": [
          "One-Step Instructions",
          "Climbing",
          "Prompt to Sit",
          "Prompt to Go to Bathroom",
          "Use Timer",
          "Prompt FCR"
        ],
        "goalCount": 4,
        "forbidCountClaims": [
          "all three"
        ],
        "promptLevelWithCount": {
          "count": [
            "2 of 3",
            "2/3",
            "2 trials",
            "two trials",
            "other 2",
            "other two"
          ],
          "level": "physical"
        },
        "forbidPhrases": [
          "Parent Goals prompted",
          "met with Parent Goals",
          "performance feedback delivered",
          "physical prompt was required on the other."
        ],
        "individualsInclude": [
          "Parent/Caregiver",
          "Client",
          "Technician"
        ],
        "caregiverResponse": "Parent/Family is trying to learn new strategies, but there are some small barriers to generalization.",
        "progressStatus": "Moderate progress towards goals",
        "followupItems": [
          1,
          3
        ]
      }
    },
    {
      "id": "v2-missed-prompt-and-a-teacher",
      "intake": "Parent training.\nClient Goals:\nManding for Breaks|independent|3/2|60%\nElopement (Bx Reduction) 1 instance during the session.\nParent Goals:\n1. Parent Goal: Deliver Token Board|Present Token Board Before Demand|4/1|80%\nCaregiver forgot the token board once before a demand, and elopement followed. Teacher reported the same pattern at school and asked to meet.",
      "answers": [],
      "expect": {
        "goalNames": [
          "Manding for Breaks",
          "Elopement",
          "Present Token Board Before Demand"
        ],
        "goalCount": 3,
        "forbidCountClaims": [
          "all two",
          "both parent goals"
        ],
        "forbidPhrases": [
          "performance feedback delivered"
        ],
        "individualsInclude": [
          "Parent/Caregiver",
          "Client",
          "Technician"
        ],
        "individualsExclude": [
          "Teacher"
        ],
        "caregiverResponse": "Parent/Family is trying to learn new strategies, but there are some small barriers to generalization.",
        "followupItems": [
          1,
          3
        ],
        "followupMentions": [
          "teacher"
        ]
      }
    },
    {
      "id": "v3-generalization-stated",
      "intake": "Parent training.\nParent Goals:\n1. Parent Goal: Use First-Then Language|At Home|5/0|100%\n2. Parent Goal: Use First-Then Language|In the Community|4/0|100%\nCaregiver used first-then language at the grocery store without a reminder from BCBA. No barriers reported. Client Goals:\nWaiting|2 minutes|4/0|100%",
      "answers": [],
      "expect": {
        "goalNames": [
          "First-Then Language",
          "Waiting"
        ],
        "goalCount": 3,
        "individualsInclude": [
          "Parent/Caregiver",
          "Client",
          "Technician"
        ],
        "caregiverResponse": "Parent/Family is responding to training and generalization of skills is occurring. There are no barriers with their training.",
        "followupItems": [
          1,
          3
        ]
      }
    },
    {
      "id": "v4-no-bt-today",
      "intake": "Parent training, caregiver and client only. Follow up when the BT is present on fading the visual schedule.\nParent Goals:\n1. Parent Goal: Follow Visual Schedule|Point to Next Picture|3/1|75%\nClient Goals:\nTransitions Between Activities|with visual|3/0|100%",
      "answers": [],
      "expect": {
        "goalNames": [
          "Point to Next Picture",
          "Transitions Between Activities"
        ],
        "goalCount": 2,
        "forbidPhrases": [
          "3 of 1",
          "3 of 0"
        ],
        "individualsInclude": [
          "Parent/Caregiver",
          "Client"
        ],
        "individualsExclude": [
          "Technician"
        ],
        "caregiverResponse": "Parent/Family is trying to learn new strategies, but there are some small barriers to generalization.",
        "followupItems": [
          1,
          3
        ],
        "followupMentions": [
          [
            "BT",
            "technician"
          ]
        ]
      }
    }
  ];

  const QUESTION_LINE = /^\s*(clarify|specify|(confirm|verify|determine|check|ask|identify) (whether|if)|find out (whether|if))\b|\?\s*$/i;
  
  const lc = (s) => String(s || '').toLowerCase();
  const anyOf = (v) => [].concat(v);
  
  function checkParentDraft(c, draft) {
    const e = c.expect || {};
    const fails = [];
    const summary = String(draft.summary || '');
    const all = `${summary}\n${draft.followup || ''}`;
  
    for (const name of e.goalNames || []) {
      if (!lc(summary).includes(lc(name))) fails.push(`goal not named in the summary: "${name}"`);
    }
    for (const claim of e.forbidCountClaims || []) {
      if (lc(summary).includes(lc(claim))) fails.push(`a goal count the list does not support: "${claim}"`);
    }
    for (const p of e.forbidPhrases || []) {
      if (lc(all).includes(lc(p))) fails.push(`a phrase that must not appear: "${p}"`);
    }
    if (e.promptLevelWithCount) {
      // count may list several ways to write the same count ("2 of 3", "2
      // trials"); Kaleb's first live run wrote one the single form missed.
      const { count, level } = e.promptLevelWithCount;
      const forms = anyOf(count);
      const sentences = summary.split(/(?<=[.!?])\s+/);
      const withCount = sentences.filter((s) => forms.some((f) => lc(s).includes(lc(f))));
      if (!withCount.length) fails.push(`the trial count ("${forms.join('" or "')}") is missing`);
      else if (!withCount.some((s) => lc(s).includes(lc(level)))) fails.push(`the trial count is written without the prompt level ("${level}") beside it`);
    }
  
    const present = draft.individualsPresent || [];
    for (const who of e.individualsInclude || []) if (!present.includes(who)) fails.push(`Individuals Present is missing "${who}"`);
    for (const who of e.individualsExclude || []) if (present.includes(who)) fails.push(`Individuals Present lists "${who}", whom the notes place out of the session`);
  
    if (e.caregiverResponse && draft.caregiverResponse !== e.caregiverResponse) {
      fails.push(`Caregiver Response picked "${draft.caregiverResponse}", expected "${e.caregiverResponse}"`);
    }
    if (e.progressStatus && draft.progressStatus !== e.progressStatus) {
      fails.push(`Progress Status picked "${draft.progressStatus}", expected "${e.progressStatus}"`);
    }
  
    const items = String(draft.followup || '').split('\n').map((s) => s.trim()).filter(Boolean);
    if (e.followupItems) {
      const [lo, hi] = e.followupItems;
      if (items.length < lo || items.length > hi) fails.push(`Follow Up has ${items.length} item(s), expected ${lo} to ${hi}`);
    }
    for (const line of items) if (QUESTION_LINE.test(line)) fails.push(`Follow Up holds a question to the author: "${line}"`);
    // An entry may list alternatives: ["BT", "technician"] is met by either.
    for (const entry of e.followupMentions || []) {
      const words = anyOf(entry);
      if (!items.some((l) => words.some((w) => lc(l).includes(lc(w))))) fails.push(`no Follow Up item mentions "${words.join('" or "')}"`);
    }
    return fails;
  }

  return (async function runParentShapeLive(CASES, checkParentDraft) {
  /* Chrome lends the console's copy() only while the pasted code first runs,
     so it is taken now, before the first await; by the time the drafts are
     back the name is gone. The report also stays on window, where typing
     copy(parentShapeReport) always works. */
  const copyNow = typeof copy === 'function' ? copy : null;
  const tool = (window.NOTE_TOOLS || []).find((t) => t.id === 'parent');
  if (!tool) throw new Error('Open the BCBA notes page with Parent Training loaded first.');
  if (!window.NotesGate || !window.NotesGate.isLoggedIn()) throw new Error('Log in first.');
  const gate = window.NotesGate;
  const HEADER = '\n\nTHE TECHNICIAN ADDED, ANSWERING FOLLOW-UP QUESTIONS (each A: answers the Q: above it, so write it where that question points; treat as part of the notes above):\n';
  const keys = tool.formSections.filter((s) => s.kind !== 'facts').map((s) => s.key || s.group);
  const narrative = tool.formSections.filter((s) => s.kind === 'narrative').map((s) => s.key || s.group);
  const card = gate.styleCard ? await gate.styleCard.get().catch(() => null) : null;
  const styleBlock = (card && card.block) || '';

  const finalize = (parsed, map) => {
    const restored = window.NotesScrub.restoreOutput(parsed, map);
    const hollow = window.NoteHollow;
    const misplaced = hollow && tool.strategyOwnership ? hollow.misplaced(restored, tool.strategyOwnership) : [];
    const gaps = hollow && hollow.effectUnstated && tool.strategyOwnership ? hollow.effectUnstated(restored, tool.strategyOwnership) : [];
    const injected = misplaced.concat(gaps);
    const withHints = injected.length
      ? { ...restored, hints: (Array.isArray(restored.hints) ? restored.hints : []).concat(injected) }
      : restored;
    const normalized = tool.normalizeOutput(withHints);
    const stripped = window.NoteAbsence ? window.NoteAbsence.scrubNote(normalized).output : normalized;
    return hollow ? hollow.passNote(stripped, narrative).output : stripped;
  };

  const draftCase = async (c) => {
    const answers = (c.answers || []).map((a) => `Q: ${a.question}\nA: ${a.answer}`).join('\n\n');
    const rev = await window.NotesScrub.review({ freeText: `${c.intake}\n${answers}`, seen: [], newNote: false });
    const scrub = (s) => window.NotesScrub.applyMap(String(s || ''), rev.map);
    const extra = scrub(answers).trim();
    const userMsg = tool.buildUserPrompt({ sessionNotes: scrub(c.intake) }) + (extra ? HEADER + extra : '');
    const shaped = gate.styleCard
      ? await gate.styleCard.get({ tool: tool.id, seed: `${tool.id}:shape-live:${c.id}:${Date.now()}` }).catch(() => null)
      : null;
    const voiceBlock = window.IntakeVoice ? window.IntakeVoice.block(`${scrub(c.intake)}${extra ? `\n${extra}` : ''}`) : '';
    const block = styleBlock + voiceBlock + ((shaped && shaped.shapeBlock) || '');
    const r = await gate.generateConversation({
      ...(tool.draftKind ? { promptKind: tool.draftKind } : {}),
      systemSuffix: block,
      messages: [{ role: 'user', content: userMsg }],
      tool: tool.id,
      maxTokens: tool.maxTokens || 3000,
      expectKeys: keys,
      responseSchema: tool.responseSchema || null,
    });
    if (!r || !r.parsed) throw new Error('the draft came back without a note');
    return { draft: finalize(r.parsed, rev.map), voice: Boolean(styleBlock || voiceBlock) };
  };

  const results = [];
  const drafts = {};
  // Each case is a full draft call, so a line per case shows the run moving.
  console.log(`Drafting ${CASES.length} notes, one after another. The table prints when the last lands.`);
  for (const [i, c] of CASES.entries()) {
    const started = Date.now();
    try {
      const { draft, voice } = await draftCase(c);
      drafts[c.id] = draft;
      const fails = checkParentDraft(c, draft);
      results.push({ case: c.id, pass: fails.length === 0, voice, fails: fails.join(' | ') || '-' });
    } catch (err) {
      results.push({ case: c.id, pass: false, voice: Boolean(styleBlock), fails: `draft failed: ${err && err.message}` });
    }
    const last = results[results.length - 1];
    console.log(`${i + 1} of ${CASES.length}: ${c.id}, ${last.pass ? 'pass' : 'fail'}, ${Math.round((Date.now() - started) / 1000)}s`);
  }

  console.table(results);
  const report = { at: new Date().toISOString(), styleCard: Boolean(styleBlock), results, drafts };
  window.parentShapeReport = report;
  try {
    if (!copyNow) throw new Error('no console copy()');
    copyNow(JSON.stringify(report, null, 2));
    console.log('The results and the four drafts are on your clipboard.');
  } catch (e) {
    console.log('To put the results on your clipboard, type copy(parentShapeReport) and press Enter.');
  }
  return report;
})(CASES, checkParentDraft);
})();
